/* ==== HORIZON NAVY COLOURS (release-hz/colors, 2026-09-24) ====================================
   The page's own colours re-pointed at the Pando 0.3.16 navy scheme (app/ui/src/styles/horizon.css).
   Colours only: no font, size, layout, link or word changes. Appended last so it wins on order.
   Meaning of each colour, as in the app:
     coral #ff8a6a  needs you     (the site's old amber; the --amber token now holds coral)
     red   #ff6b78  failed        (the site's old coral; the --coral token now holds red)
     green #7ee0a6  working, passed
     ice   #8fe3ff  memory, the Brain
     white #f2f6fb  you: primary buttons, focus (navy ink on it)
   Text ramp keeps the old weights; --faint is lifted so fine print clears 4.5:1 on every ground. */
:root{
  --bg:#050c17;--panel:#0f1c2f;--panel2:#0a1524;--row:#16263d;--chip:#1c2f4a;
  --edge:rgba(150,185,235,.18);--hair:rgba(150,185,235,.14);
  --ink:#ecf2fa;--ink2:#9aabc2;--ink3:#7d8fa7;--faint:#74869d;
  --accent:#f2f6fb;--accent-h:#ffffff;--accent-ink:#050c17;--mint:#ecf2fa;
  --glow:0 0 0 1px rgba(236,242,250,.35),0 0 26px rgba(236,242,250,.24);
  --green:#7ee0a6;--amber:#ff8a6a;--coral:#ff6b78;--ice:#8fe3ff
}
/* the window replicas' own tokens, re-pointed at navy exactly as the app's horizon.css re-points the
   Workbench graphite family, so a replica never falls back to graphite under the navy page */
.win,.shot-in{
  --g0:#050c17;--g1:#0a1524;--g2:#0f1c2f;--g3:#16263d;--g4:#1c2f4a;
  --l1:rgba(150,185,235,.16);--l2:rgba(150,185,235,.09);
  --i1:#ecf2fa;--i2:#c3cfdf;--i3:#9aabc2;--i4:#7d8fa7;
  --wb-glow:0 0 0 1px rgba(236,242,250,.22),0 0 22px rgba(143,227,255,.10)
}
/* page ground, intro, selection */
html{background:var(--bg)!important}
#root,#intro{background:var(--bg)}
::selection{background:rgba(236,242,250,.28)}
/* buttons */
.btn:hover{background:var(--row);border-color:rgba(150,185,235,.3)}
.btn.primary:hover{box-shadow:0 0 0 1px rgba(236,242,250,.5),0 0 36px rgba(236,242,250,.4)}
/* launch banner and nav */
.lbar{box-shadow:0 0 40px rgba(236,242,250,.2)}
.lbar a:hover{background:var(--chip)}
.lbar .lx{color:rgba(5,12,23,.7)}
.site-header::before{background:linear-gradient(to bottom,rgba(5,12,23,.92),rgba(5,12,23,.6) 55%,rgba(5,12,23,0))}
.nav a:hover{background:rgba(150,185,235,.08)}
/* film: stop cards; the Brain chapter's lamps, glow and number are ice (memory); Review's are coral via --amber */
.stop{background:rgba(15,28,47,.94);box-shadow:inset 0 1px 0 rgba(150,185,235,.08)}
.screen[data-i="3"],.stop[data-i="3"]{--acc:var(--ice)!important}
/* pricing */
.bill button em{background:rgba(150,185,235,.16)}
.bill button.on,.bill button.on em{color:var(--accent-ink)}
.bill button.on em{background:rgba(5,12,23,.12)}
/* the founding card: neutral navy, not amber (coral means needs you, and this card does not) */
.founder{border-color:rgba(150,185,235,.28);background:rgba(150,185,235,.05)}
.founder-tag,.founder-left{color:var(--ink)}
/* ==== end HORIZON NAVY COLOURS ==== */
/* ==== film descriptions: words only, no card (nocard-2026-09-25) ==== */
/* Wide screens, animated film only (reduced motion keeps its cards); the phone layout already has no card, and at 900px and under the words sit on the window so the card stays.
   A soft navy shade with no edge keeps the words readable over the scene; the light beam on the words side of each window is off. */
@media (min-width:901px){
html:not(.rm) .stage .stop{background:none;border:0;border-radius:0;box-shadow:none;padding:0;width:min(320px,27vw - 60px)}
html:not(.rm) .stage .stop::before{content:"";position:absolute;inset:-32% -46%;z-index:-1;pointer-events:none;background:radial-gradient(50% 50% at 50% 50%,rgba(5,12,23,.96),rgba(5,12,23,.9) 52%,rgba(5,12,23,0) 100%)}
html:not(.rm) .screen[data-i="0"] .lamp.l,html:not(.rm) .screen[data-i="2"] .lamp.l,html:not(.rm) .screen[data-i="4"] .lamp.l,html:not(.rm) .screen[data-i="1"] .lamp.r,html:not(.rm) .screen[data-i="3"] .lamp.r,html:not(.rm) .screen[data-i="5"] .lamp.r{display:none}
}
/* ==== end no card ==== */

