/* --- Draft: workspace demo icon rail (floats over the sidebar mock) --- */
.pando-static-page .pando-rail {
  position: absolute; left: 0; top: 0; bottom: 0; z-index: 6;
  box-sizing: border-box; width: 58px;
  display: flex; flex-direction: column;
  padding: 14px 7px 10px; overflow: hidden;
  background: var(--g1); border-right: 1px solid var(--l1);
  box-shadow: 2px 0 18px rgba(0,0,0,.28);
  transition: width 420ms cubic-bezier(.22,1,.36,1);
}
.pando-static-page .pando-rail.is-open,
.pando-static-page .pando-rail:focus-within { width: 204px; }
.pando-static-page .pando-rail-top { position: relative; display: flex; flex-direction: column; gap: 8px; }
.pando-static-page .pando-tile {
  position: absolute; left: 0; top: 0; z-index: 0; pointer-events: none;
  width: 44px; height: 44px; border-radius: 8px; background: #fff;
  transition: top 360ms cubic-bezier(.22,1,.36,1);
}
.pando-static-page .pando-rail-item {
  position: relative; z-index: 1;
  display: flex; align-items: center; gap: 12px;
  width: 100%; height: 44px; min-height: 44px; padding: 0; border: 0;
  border-radius: 8px; background: var(--g3); color: var(--i2);
  font: inherit; text-align: left; cursor: pointer;
  transition: background .16s, color .16s;
}
.pando-static-page .pando-rail-item .pr-ico { flex: none; width: 44px; height: 44px; display: grid; place-items: center; }
.pando-static-page .pando-rail-item .pr-ico svg { width: 18px; height: 18px; }
.pando-static-page .pando-rail-item .pr-label {
  white-space: nowrap; font-size: 13px; font-weight: 550;
  opacity: 0; transition: opacity 200ms ease;
}
.pando-static-page .pando-rail.is-open .pando-rail-item .pr-label,
.pando-static-page .pando-rail:focus-within .pando-rail-item .pr-label {
  opacity: 1; transition: opacity 200ms ease 90ms;
}
.pando-static-page .pando-rail-item.is-active { background: transparent; color: #111; }
.pando-static-page .pando-rail-item.is-active .pr-ico svg { color: #111; }
.pando-static-page .pando-rail-item:not(.is-active):hover { background: var(--g4); color: var(--i1); }
.pando-static-page .pando-rail-toggle {
  margin-top: auto; flex: none; align-self: flex-start;
  width: 44px; height: 32px; display: grid; place-items: center;
  border: 0; border-radius: 8px; background: var(--g3); color: var(--i2); cursor: pointer;
}
.pando-static-page .pando-rail-toggle svg { width: 16px; height: 16px; transition: transform 420ms cubic-bezier(.22,1,.36,1); }
.pando-static-page .pando-rail.is-open .pando-rail-toggle svg,
.pando-static-page .pando-rail:focus-within .pando-rail-toggle svg { transform: rotate(180deg); }
